import 'package:flutter/material.dart';
import 'question.dart';
import 'database_service.dart';
import 'main.dart';
class SimuladoScreen extends StatefulWidget{const SimuladoScreen({super.key});@override State<SimuladoScreen> createState()=>_SimuladoScreenState();}
class _SimuladoScreenState extends State<SimuladoScreen>{int count=10;String subject='Todas';List<String> subjects=['Todas'];List<Question> quiz=[];int index=0,correct=0;String? chosen;bool answered=false,finished=false;
@override void initState(){super.initState();DatabaseService.instance.values('subject').then((v){if(mounted)setState(()=>subjects=v);});}
Future<void> start()async{final all=await DatabaseService.instance.list(subject:subject,limit:1000);all.shuffle();final chosenQuestions=all.take(count).toList();if(chosenQuestions.isEmpty){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Importe ou adicione questões para começar.')));return;}setState((){quiz=chosenQuestions;index=0;correct=0;chosen=null;answered=false;finished=false;});}
Future<void> next()async{final q=quiz[index];if(!answered){await DatabaseService.instance.recordAttempt(q,chosen!);if(chosen==q.answer)correct++;setState(()=>answered=true);return;}if(index+1<quiz.length){setState((){index++;chosen=null;answered=false;});}else{await DatabaseService.instance.recordSession(quiz.length,correct);setState(()=>finished=true);}}
@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Simulado')),body:finished?Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.emoji_events,color:lime,size:60),const SizedBox(height:12),const Text('Simulado concluído!',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),Text('$correct de ${quiz.length} acertos (${(correct/quiz.length*100).round()}%)'),const SizedBox(height:18),FilledButton(onPressed:start,child:const Text('Novo simulado'))]))):quiz.isEmpty?ListView(padding:const EdgeInsets.all(20),children:[const Text('Monte seu treino',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:16),DropdownButtonFormField<String>(value:subject,decoration:const InputDecoration(labelText:'Assunto'),items:subjects.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v)=>setState(()=>subject=v??'Todas')),const SizedBox(height:18),const Text('Quantidade de questões'),Slider(value:count.toDouble(),min:1,max:30,divisions:29,label:'$count',onChanged:(v)=>setState(()=>count=v.round())),Text('$count questões'),const SizedBox(height:18),FilledButton(onPressed:start,child:const Text('Iniciar simulado'))]):ListView(padding:const EdgeInsets.all(18),children:[Text('Questão ${index+1} de ${quiz.length}',style:const TextStyle(color:lime,fontWeight:FontWeight.bold)),const SizedBox(height:12),Text(quiz[index].prompt,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:14),...List.generate(5,(i){final q=quiz[index];if(q.options[i].trim().isEmpty)return const SizedBox.shrink();final l='ABCDE'[i];return Card(child:RadioListTile<String>(value:l,groupValue:chosen,title:Text('$l) ${q.options[i]}'),onChanged:answered?null:(v)=>setState(()=>chosen=v)));}),if(answered)Card(child:Padding(padding:const EdgeInsets.all(12),child:Text('Gabarito: ${quiz[index].answer}\n${quiz[index].explanation}'))),const SizedBox(height:12),FilledButton(onPressed:chosen==null?null:next,child:Text(answered?(index+1==quiz.length?'Finalizar':'Próxima questão'):'Confirmar resposta'))]));}
}
